#!/usr/bin/env bash
# Checks that generated files are untouched: each still matches what its generator makes from the
# current source, nothing generated is copied where it should be linked, and no build output is
# tracked.
#
#   code/qa/check-generated.sh
#
# 1. Build output and generated-and-ignored files (lib/, dist/, build/, functions/src/shared/,
#    *.xcodeproj, node_modules, ...) aren't tracked: `git ls-files -ci --exclude-standard` is empty.
# 2. The shared contracts and design-system/tokens.css are current (code/shared generators, --check).
# 3. design-system/components/Mascot3D/preview.html matches tools/build-mascot-preview.mjs, run on a
#    scratch copy so the real file is never written.
# 4. Generated shared code is linked, never copied: TMLCore's Contracts and Tokens are symlinks into
#    code/shared, and no file outside code/shared/*/generated/ carries a code/shared generator header.
# 5. The iOS asset catalogs' mascot and brand-mark files are byte-identical to their design-system
#    and brand sources (code/ios/scripts/export-assets.sh copies them).
# 6. The FSD PDF is never edited by hand: if it changed, Track Me Live — FSD.md or docs/fsd-pdf/
#    changed too; and if the FSD changed, the PDF was rebuilt. "Changed" means uncommitted changes,
#    plus the commits since TML_BASE_REF when that is set (CI sets it to the PR base).
#
# Needs git and Node 22.6+. No network. Exit status: 0 when everything holds, 1 otherwise.
set -euo pipefail

QA_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)"
REPO="$(cd "${QA_DIR}/../.." && pwd -P)"
cd "${REPO}"

failures=0
fail() { printf 'FAIL: %s\n' "$*"; failures=$((failures + 1)); }
ok() { printf 'ok:   %s\n' "$*"; }

scratch="$(mktemp -d)"
trap 'rm -rf "${scratch}"' EXIT

# 1. Nothing ignored is tracked.
tracked_ignored="$(git ls-files -ci --exclude-standard)"
if [[ -n "${tracked_ignored}" ]]; then
  fail "tracked files that .gitignore marks as build output or local files (git rm --cached them):"
  printf '%s\n' "${tracked_ignored}" | sed 's/^/        /'
else
  ok "no build output or ignored file is tracked"
fi

# 2. Shared contracts and design-system/tokens.css.
for generator in code/shared/tokens/build.mjs code/shared/schema/build.mjs; do
  if [[ ! -f "${generator}" ]]; then
    fail "${generator} is missing"
  elif output="$(node "${generator}" --check 2>&1)"; then
    ok "${generator} --check: ${output//$'\n'/; }"
  else
    fail "${generator} --check:"
    printf '%s\n' "${output}" | sed 's/^/        /'
  fi
done

# 3. The design system's live 3D mascot card, regenerated in a scratch tree.
preview="design-system/components/Mascot3D/preview.html"
if [[ -f "design-system/tools/build-mascot-preview.mjs" && -f "${preview}" ]]; then
  mkdir -p "${scratch}/ds/design-system/tools" "${scratch}/ds/design-system/components/Mascot3D" "${scratch}/ds/mascots"
  cp design-system/tools/build-mascot-preview.mjs "${scratch}/ds/design-system/tools/"
  cp design-system/design-system.json "${scratch}/ds/design-system/"
  cp -R mascots/model "${scratch}/ds/mascots/model"
  if ! node "${scratch}/ds/design-system/tools/build-mascot-preview.mjs" > "${scratch}/mascot-preview.log" 2>&1; then
    fail "build-mascot-preview.mjs failed:"
    sed 's/^/        /' "${scratch}/mascot-preview.log"
  elif cmp -s "${preview}" "${scratch}/ds/${preview}"; then
    ok "${preview} matches design-system/tools/build-mascot-preview.mjs"
  else
    fail "${preview} differs from what design-system/tools/build-mascot-preview.mjs makes. Don't edit it; run: node design-system/tools/build-mascot-preview.mjs"
  fi
fi

# 4. Linked, never copied.
core="code/ios/Packages/TMLCore/Sources/TMLCore"
check_link() { # <link> <target it must resolve to>
  local resolved
  if [[ ! -L "$1" ]]; then
    fail "$1 must be a symlink to $2 (it's generated; link it, don't copy it)"
  elif ! resolved="$(cd "$1" 2>/dev/null && pwd -P)" || [[ "${resolved}" != "${REPO}/$2" ]]; then
    fail "$1 must resolve to $2"
  else
    ok "$1 -> $2"
  fi
}
if [[ -d "${core}" ]]; then
  check_link "${core}/Contracts" "code/shared/schema/generated/swift"
  check_link "${core}/Tokens" "code/shared/tokens/generated/swift"
fi
copies="$(git grep --untracked -I -l -E '^(//|#|/\*|<!--)?[[:space:]]*Generated by code/shared/' -- . \
  ':(exclude)code/shared/*/generated/**' ':(exclude)code/shared/*/build.mjs' || true)"
if [[ -n "${copies}" ]]; then
  fail "copies of generated shared files (reference code/shared/*/generated/ in place instead):"
  printf '%s\n' "${copies}" | sed 's/^/        /'
else
  ok "no copies of code/shared generated files"
fi

# 5. Exported asset copies in the iOS catalogs.
asset_total=0
asset_bad=0
check_copy() { # <copy> <source>
  [[ -f "$2" ]] || return 0
  asset_total=$((asset_total + 1))
  if ! cmp -s "$1" "$2"; then
    fail "$1 differs from its source $2. Change the source, then run code/ios/scripts/export-assets.sh"
    asset_bad=$((asset_bad + 1))
  fi
}
for set in code/ios/TrackMeLive/Resources/Assets.xcassets/mascot-*.imageset \
           code/ios/TrackMeLiveWidgets/Assets.xcassets/mascot-*.imageset; do
  [[ -d "${set}" ]] || continue
  name="$(basename "${set}" .imageset)"
  id="${name#mascot-}"
  if [[ "${id}" == *-flat ]]; then
    check_copy "${set}/${name}.svg" "design-system/assets/Mascots/${id%-flat}.svg"
  else
    check_copy "${set}/${name}.png" "design-system/assets/Mascots/${id}.png"
  fi
done
mark="code/ios/TrackMeLive/Resources/Assets.xcassets/brand-mark.imageset"
if [[ -d "${mark}" ]]; then
  check_copy "${mark}/brand-mark.svg" "brand/logo/mark.svg"
  check_copy "${mark}/brand-mark-dark.svg" "brand/logo/mark-on-dark.svg"
fi
if (( asset_total > 0 && asset_bad == 0 )); then
  ok "${asset_total} iOS asset catalog files match their design-system and brand sources"
fi

# 6. The FSD PDF and its source. Paths come NUL-separated, so git never quotes them.
changed="${scratch}/changed"
{
  git diff -z --name-only HEAD --
  git ls-files -z --others --exclude-standard
  if [[ -n "${TML_BASE_REF:-}" ]]; then
    if git rev-parse --verify --quiet "${TML_BASE_REF}^{commit}" > /dev/null; then
      git diff -z --name-only "${TML_BASE_REF}...HEAD" --
    else
      echo "note: TML_BASE_REF=${TML_BASE_REF} isn't a commit here; checking uncommitted changes only" >&2
    fi
  fi
} | tr '\0' '\n' > "${changed}"
is_changed() { grep -Fxq -- "$1" "${changed}"; }
is_changed_under() { grep -q -- "^$1" "${changed}"; }
fsd_md="Track Me Live — FSD.md"
fsd_pdf="Track Me Live — FSD.pdf"
if is_changed "${fsd_pdf}" && ! is_changed "${fsd_md}" && ! is_changed_under "docs/fsd-pdf/"; then
  fail "${fsd_pdf} changed but ${fsd_md} and docs/fsd-pdf/ didn't. Never edit the PDF; edit the FSD, then run: npm --prefix docs/fsd-pdf run build"
elif is_changed "${fsd_md}" && ! is_changed "${fsd_pdf}"; then
  fail "${fsd_md} changed but the PDF wasn't rebuilt. Run: npm --prefix docs/fsd-pdf run build"
else
  ok "the FSD PDF and its source agree"
fi

if (( failures > 0 )); then
  echo "check-generated: ${failures} problem(s)"
  exit 1
fi
echo "check-generated: all generated files are untouched"
